import catalog_sync_validation as v,warehouse_catalog as wc
p=argparse.ArgumentParser();p.add_argument('--file',type=Path,required=True);p.add_argument('--exe',type=Path,required=True);p.add_argument('--rows',type=int,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);file=a.file.resolve();exe=a.exe.resolve();req=out/'request.json';res=out/'result.json';req.write_text(json.dumps({'schema':1,'file':str(file),'warehouse':'山东仓','sha256':v.digest(file),'expected_rows':a.rows,'candidate':str(out/'candidate.json')}),'utf-8');env=os.environ.copy();env['REPLENISHMENT_DATA_DIR']=str(out/'must-not-exist');start=time.perf_counter();r=subprocess.run([str(exe),'--catalog-validate','--request',str(req),'--result',str(res)],env=env,timeout=90);elapsed=time.perf_counter()-start;receipt=json.loads(res.read_text('utf-8'));actual=v.candidate(receipt);manual=wc.import_catalog(file,'山东仓');equal=json.dumps(actual['items'],ensure_ascii=False)==json.dumps(manual['items'],ensure_ascii=False);passed=r.returncode==0 and equal and not receipt['qt_imported'] and not (out/'must-not-exist').exists();report={'passed':passed,'rows':len(actual['items']),'business_values_types_and_order_equal':equal,'qt_imported':receipt['qt_imported'],'exit_code':r.returncode,'seconds':elapsed,'exe_sha256':v.digest(exe),'source_sha256':v.digest(file)};(out/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),'utf-8');print(json.dumps(report,ensure_ascii=False))
